using namespace detail;
struct Identity {};
struct AssetData {explicit AssetData(std::shared_ptr<AssetLease> lease):bank(std::move(lease)){} Bank bank;std::uint64_t serial{};};
namespace {
#include "../source_records.inc"
struct Slot {bool active{},retired{};std::uint64_t generation{1},epoch{};};
struct Garbage {
    std::array<std::shared_ptr<const DecodedSample>,voice_capacity*2> clips;
    std::array<std::shared_ptr<const AssetData>,port_count> assets;
    std::size_t count{};
};
struct Frame {
    const State* state;Frame* previous;
    static thread_local Frame* current;
    explicit Frame(const State* value):state(value),previous(current){current=this;}
    ~Frame(){current=previous;}
    static bool contains(const State* value){for(auto* f=current;f;f=f->previous)if(f->state==value)return true;return false;}
};
thread_local Frame* Frame::current=nullptr;
}
struct State {
    Config config;
    std::shared_ptr<Budget> budget;
    std::shared_ptr<const Identity> identity=std::make_shared<Identity>();
    mutable std::mutex data,gate;
    std::mutex lifecycle;
    std::condition_variable changed;
    std::atomic<bool> closed{};
    std::atomic<std::uint64_t> epoch{1};
    std::uint64_t next_asset_serial{1};
    std::vector<Slot> submissions;
    std::size_t calls{},producers{};
    bool joined{};
    std::array<Port,port_count> ports;
    std::vector<Voice> voices;
    std::vector<Event> events;
    std::vector<Sample> samples;
    std::array<std::shared_ptr<const DecodedSample>,voice_capacity> retired;
    std::size_t retired_count{};
    std::uint64_t requestAge{},frameClock{};
    bool muted{},mono{},pathLog{};
    Diagnostics diagnostics;
    struct BankPathCounters {std::uint64_t activeVoiceFrames{},signalVoiceFrames{},requests{};};
    std::array<std::array<BankPathCounters,128>,port_count> pathCounters{};
    explicit State(Config c):config(c),budget(std::make_shared<Budget>(c.max_asset_bytes,c.max_assets,c.allocation_source)),submissions(c.max_submissions),pathLog(c.path_counters) {
        if(!c.max_submissions||!c.max_render_frames||!c.max_generation)throw std::invalid_argument("Invalid bounded bank session");
        voices.reserve(voice_capacity);events.reserve(1025);samples.reserve(255u*255u);
    }
    struct Call {
        State& state;Frame frame;bool admitted{};
        explicit Call(State& s):state(s),frame(&s){std::lock_guard lock(s.gate);if(!s.closed.load()){++s.calls;admitted=true;}}
        ~Call(){if(admitted){std::lock_guard lock(state.gate);--state.calls;state.changed.notify_all();}}
    };
    Status valid_submission(std::uint32_t slot,std::uint64_t generation) const {
        std::lock_guard lock(gate);
        if(slot>=submissions.size()||!submissions[slot].active||submissions[slot].generation!=generation)return Status::invalid_submission;
        if(closed.load())return Status::closed;
        return submissions[slot].epoch==epoch.load()?Status::ok:Status::stale_generation;
    }
    void collect_retired(Garbage& out) {
        for(std::size_t n=0;n<retired_count;++n)out.clips[out.count++]=std::move(retired[n]);
        retired_count=0;
    }
    void clear_locked(Garbage& out) {
        collect_retired(out);
        for(auto& voice:voices)if(voice.data)out.clips[out.count++]=std::move(voice.data);
        voices.clear();
        for(unsigned p=0;p<port_count;++p)out.assets[p]=std::move(ports[p].asset);
        ports={};requestAge=frameClock=0;muted=mono=false;diagnostics={};pathCounters={};
    }
    void report(const char* kind,unsigned value) {
        DiagnosticKind type=DiagnosticKind::global_control;
        if(!std::strcmp(kind,"velocity-curve"))type=DiagnosticKind::velocity_curve;
        else if(!std::strcmp(kind,"sample-decode"))type=DiagnosticKind::sample_decode;
        else if(!std::strcmp(kind,"voice-capacity"))type=DiagnosticKind::voice_capacity;
        else if(!std::strcmp(kind,"TQ-control"))type=DiagnosticKind::tq_control;
        else if(!std::strcmp(kind,"TQ-opcode"))type=DiagnosticKind::tq_opcode;
        record(type,value);
    }
    void record(DiagnosticKind type,std::uint32_t value) {
        if(diagnostics.unsupported!=UINT64_MAX)++diagnostics.unsupported;
        if(diagnostics.event_count<diagnostics.events.size())diagnostics.events[diagnostics.event_count++]={type,value};
    }
    Status numeric_failure(){closed.store(true);return Status::numeric_domain;}
    void reclaim_inactive() {
        // A current port asset is strongly held throughout this lock and owns
        // its immutable decoded cache. Releasing such a Voice lease cannot be
        // the last clip release. Old-asset leases ALWAYS move to control retire
        // storage, without a racy use_count() decision.
        for(auto& v:voices)if(!v.active&&v.data) {
            if(!ports[v.port].asset||v.asset_serial!=ports[v.port].asset->serial)
                retired[retired_count++]=std::move(v.data);
            else v.data.reset();
        }
        voices.erase(std::remove_if(voices.begin(),voices.end(),[](const Voice& v){return !v.active;}),voices.end());
    }
#include "../source_members.inc"
    Status mix_locked(float* stereo,unsigned frames,const std::array<std::array<float,16>,14>& gains) {
#include "../source_mix.inc"
        return Status::ok;
    }
    Status apply_one(const Command& command) {
        return std::visit([&](const auto& c)->Status {
            using T=std::decay_t<decltype(c)>;
            if constexpr(std::is_same_v<T,StartRequest>)request(c.port,c.index,c.group,c.volume,c.pan,c.pitch,c.program_offset,false,false);
            else if constexpr(std::is_same_v<T,ChangeRequest>)request(c.port,c.index,c.group,c.volume,c.pan,c.pitch,0,true,false);
            else if constexpr(std::is_same_v<T,CancelRequest>)request(c.port,c.index,c.group,255,255,65535,0,true,true);
            else if constexpr(std::is_same_v<T,StopAll>){for(unsigned p=0;p<port_count;++p){stop(p);if(c.unload)ports[p].loaded=false;}}
            else if constexpr(std::is_same_v<T,StopPort>){if(c.port>=port_count)return Status::invalid_input;stop(c.port);if(c.unload)ports[c.port].loaded=false;}
            else if constexpr(std::is_same_v<T,SetAllVolumes>){for(auto& p:ports)p.volume=c.value;}
            else if constexpr(std::is_same_v<T,SetPortVolume>){if(c.port>=port_count)return Status::invalid_input;ports[c.port].volume=c.value;}
            else if constexpr(std::is_same_v<T,SetMuted>)muted=c.value;
            else if constexpr(std::is_same_v<T,SetMono>)mono=c.value;
            else if constexpr(std::is_same_v<T,UnsupportedControl>)record(c.kind,c.value);
            return Status::ok;
        },command);
    }
};
Submission::Submission(std::shared_ptr<State> state,std::uint32_t slot,std::uint64_t generation) noexcept
    :state_(std::move(state)),slot_(slot),generation_(generation){}
Submission::Submission(Submission&& other) noexcept
    :state_(std::move(other.state_)),slot_(std::exchange(other.slot_,UINT32_MAX)),generation_(other.generation_){}
Submission& Submission::operator=(Submission&& other) noexcept {
    if(this!=&other){release();state_=std::move(other.state_);slot_=std::exchange(other.slot_,UINT32_MAX);generation_=other.generation_;}return *this;
}
Submission::~Submission(){release();}
void Submission::release() noexcept {
    auto state=std::move(state_);if(!state)return;
    {std::lock_guard lock(state->gate);auto& slot=state->submissions[slot_];slot.active=false;
        if(slot.generation==state->config.max_generation)slot.retired=true;else ++slot.generation;
        --state->producers;state->changed.notify_all();}
    slot_=UINT32_MAX; // Last strong State destruction, if any, is outside gate.
}
std::uint64_t PreparedBank::fingerprint() const noexcept{return data_?data_->bank.fingerprint():0;}
unsigned PreparedBank::sequence_count() const noexcept{return data_?data_->bank.sequenceCount():0;}
Session::Session(Config c):state_(std::make_shared<State>(c)){}
Session::~Session()=default;
Result<Submission> Session::begin_submission() noexcept {
    auto& s=*state_;std::lock_guard lock(s.gate);if(s.closed.load())return {Status::closed,{}};
    for(std::size_t n=0;n<s.submissions.size();++n)if(!s.submissions[n].active&&!s.submissions[n].retired) {
        auto& slot=s.submissions[n];slot.active=true;slot.epoch=s.epoch.load();++s.producers;
        return {Status::ok,Submission(state_,static_cast<std::uint32_t>(n),slot.generation)};
    }
    return {Status::capacity,{}};
}
std::shared_ptr<const Budget> Session::budget_observer() const noexcept{return state_->budget;}
Result<CapturedBank> Session::capture(const Submission& submission,BankSizes sizes) noexcept {
    auto& s=*state_;
    if(submission.state_.get()!=&s)return {Status::invalid_submission,{}};
    const auto valid=s.valid_submission(submission.slot_,submission.generation_);if(valid!=Status::ok)return {valid,{}};
    constexpr std::size_t part_limit=2u*1024u*1024u;
    if(sizes.hd>part_limit||sizes.bd>part_limit||sizes.tq>part_limit)return {Status::invalid_asset,{}};
    std::uint64_t epoch{};{std::lock_guard lock(s.gate);epoch=s.submissions[submission.slot_].epoch;}
    try {
        auto lease=acquire_asset(s.budget);
        CapturedBank result(std::move(lease),s.identity,epoch);
        result.hd_.resize(sizes.hd);result.bd_.resize(sizes.bd);result.tq_.resize(sizes.tq);
        const auto after=s.valid_submission(submission.slot_,submission.generation_);if(after!=Status::ok)return {after,{}};
        return {Status::ok,std::move(result)};
    }catch(const BudgetExceeded&){return {Status::capacity,{}};}
    catch(const std::bad_alloc&){return {Status::no_memory,{}};}
}
Result<PreparedBank> Session::prepare(const Submission& submission,CapturedBank bytes) noexcept {
    auto& s=*state_;
    if(submission.state_.get()!=&s)return {Status::invalid_submission,{}};
    const auto valid=s.valid_submission(submission.slot_,submission.generation_);if(valid!=Status::ok)return {valid,{}};
    if(!bytes.lease_||bytes.owner_.lock()!=s.identity)return {Status::invalid_asset,{}};
    if(bytes.epoch_!=s.epoch.load())return {Status::stale_generation,{}};
    std::uint64_t epoch{},serial{};
    {std::lock_guard lock(s.gate);epoch=s.submissions[submission.slot_].epoch;
        if(s.next_asset_serial==UINT64_MAX)return {Status::counter_limit,{}};
        serial=s.next_asset_serial++;}
    try {
        auto data=std::allocate_shared<AssetData>(AssetAllocator<AssetData>(bytes.lease_),bytes.lease_);data->serial=serial;
        if(!data->bank.load(bytes.hd_.data(),bytes.hd_.size(),bytes.bd_.data(),bytes.bd_.size(),bytes.tq_.data(),bytes.tq_.size()))return {Status::invalid_asset,{}};
        const auto after=s.valid_submission(submission.slot_,submission.generation_);if(after!=Status::ok)return {after,{}};
        PreparedBank result;result.data_=std::move(data);result.owner_=s.identity;result.epoch_=epoch;
        return {Status::ok,std::move(result)};
    }catch(const BudgetExceeded&){return {Status::capacity,{}};}
    catch(const std::bad_alloc&){return {Status::no_memory,{}};}
}
Status Session::install(const Submission& submission,unsigned port,const PreparedBank& asset,LoadPolicy policy) noexcept {
    auto& s=*state_;State::Call call(s);if(!call.admitted)return Status::closed;
    if(submission.state_.get()!=&s)return Status::invalid_submission;
    if(port>=port_count)return Status::invalid_input;
    Garbage garbage;
    std::lock_guard lock(s.data);
    const auto valid=s.valid_submission(submission.slot_,submission.generation_);if(valid!=Status::ok)return valid;
    if(policy==LoadPolicy::if_unloaded&&s.ports[port].loaded)return Status::skipped;
    if(!asset.data_||asset.owner_.lock()!=s.identity)return Status::invalid_asset;
    if(asset.epoch_!=s.epoch.load())return Status::stale_generation;
    // Atomic with replacement: any previous render retirement is collected
    // before this install creates more old-asset voices. Destruction is after
    // data unlock, via the earlier-declared control-side Garbage object.
    s.collect_retired(garbage);s.stop(port);
    garbage.assets[port]=std::move(s.ports[port].asset);
    s.ports[port].asset=asset.data_;s.ports[port].fingerprint=asset.data_->bank.fingerprint();s.ports[port].loaded=true;
    if(s.diagnostics.loads!=UINT64_MAX)++s.diagnostics.loads;
    return Status::ok;
}
ApplyResult Session::apply(std::span<const Command> commands) noexcept {
    auto submission=begin_submission();if(submission.status!=Status::ok)return {submission.status,0};
    return apply(submission.value,commands);
}
ApplyResult Session::apply(const Submission& submission,std::span<const Command> commands) noexcept {
    auto& s=*state_;State::Call call(s);if(!call.admitted)return {Status::closed,0};
    if(submission.state_.get()!=&s)return {Status::invalid_submission,0};
    Garbage garbage;std::lock_guard lock(s.data);
    const auto valid=s.valid_submission(submission.slot_,submission.generation_);if(valid!=Status::ok)return {valid,0};
    s.collect_retired(garbage);
    std::size_t count=0;for(const auto& command:commands){const auto status=s.apply_one(command);if(status!=Status::ok)return {status,count};++count;}
    return {Status::ok,count};
}
Result<std::uint32_t> Session::port_state(unsigned port,std::uint32_t& sequences) const noexcept {
    auto& s=*state_;State::Call call(s);if(!call.admitted)return {Status::closed,0};
    std::lock_guard lock(s.data);sequences=port<port_count&&s.ports[port].loaded?s.ports[port].asset->bank.sequenceCount():0;
    return {Status::ok,port<port_count&&s.ports[port].loaded?1u:0u};
}
Result<std::uint32_t> Session::sequence_state(unsigned port,unsigned index,unsigned group) const noexcept {
    auto& s=*state_;State::Call call(s);if(!call.admitted)return {Status::closed,0};
    std::lock_guard lock(s.data);if(port<port_count)for(const auto& r:s.ports[port].requests)
        if(r.sequence.active()&&r.index==(index&127)&&r.group==(group&127))return {Status::ok,1};
    return {Status::ok,0};
}
Result<std::uint32_t> Session::pending_loads() const noexcept {
    auto& s=*state_;State::Call call(s);return {call.admitted?Status::ok:Status::closed,0};
}
Status Session::mix_add(float* stereo,std::uint32_t frames,GainProvider& provider) noexcept {
    auto& s=*state_;State::Call call(s);if(!call.admitted)return Status::closed;
    if(!stereo||!frames)return Status::ok;
    if(frames>s.config.max_render_frames)return Status::invalid_input;
    std::lock_guard lock(s.data);
    std::size_t old=0;for(const auto& v:s.voices)if(v.data&&(!s.ports[v.port].asset||v.asset_serial!=s.ports[v.port].asset->serial))++old;
    if(old>voice_capacity-s.retired_count)return Status::capacity;
    std::array<std::array<float,16>,14> gains{};bool valid=true;
    for(unsigned p=0;p<port_count;++p)for(unsigned q=0;q<request_count;++q){const auto value=provider.gain(p,s.ports[p].requests[q].index,s.ports[p].fingerprint);gains[p][q]=value;valid&=std::isfinite(value)&&value>=0&&value<=8;}
    if(!valid){s.closed.store(true);return Status::unsupported_gain;}
    return s.mix_locked(stereo,frames,gains);
}
Status Session::reset() noexcept {
    auto& s=*state_;State::Call call(s);if(!call.admitted)return Status::closed;
    Garbage garbage;std::lock_guard lock(s.data);
    if(s.epoch.load()==s.config.max_generation){s.closed.store(true);return Status::counter_limit;}
    s.epoch.fetch_add(1);s.clear_locked(garbage);return Status::ok;
}
void Session::request_stop() noexcept{state_->closed.store(true,std::memory_order_release);}
bool Session::join() noexcept {
    auto state=state_;auto& s=*state;request_stop();if(Frame::contains(&s))return false;
    std::lock_guard lifecycle(s.lifecycle);if(s.joined)return true;
    {std::unique_lock lock(s.gate);s.changed.wait(lock,[&]{return !s.calls&&!s.producers;});}
    Garbage garbage;{std::lock_guard lock(s.data);s.clear_locked(garbage);}s.joined=true;return true;
}
Status Session::drain_retired() noexcept {
    auto& s=*state_;State::Call call(s);if(!call.admitted)return Status::closed;
    Garbage garbage;std::lock_guard lock(s.data);s.collect_retired(garbage);return Status::ok;
}
Snapshot Session::snapshot() const noexcept {
    auto& s=*state_;std::lock_guard lock(s.data);Snapshot out;
    out.voice_count=s.voices.size();out.retired_clips=s.retired_count;out.request_age=s.requestAge;out.frame_clock=s.frameClock;out.muted=s.muted;out.mono=s.mono;out.diagnostics=s.diagnostics;
    for(unsigned p=0;p<port_count;++p){const auto& from=s.ports[p];auto& to=out.ports[p];to.loaded=from.loaded;to.volume=from.volume;to.fingerprint=from.fingerprint;to.sequence_count=from.asset?from.asset->bank.sequenceCount():0;
        for(unsigned n=0;n<request_count;++n){const auto& r=from.requests[n];to.requests[n]={r.sequence.observe(),r.index,r.group,r.priority,r.cancelFlags,r.requestVolume,r.requestPan,r.requestPitch,r.pitch,r.program,r.volume,r.expression,r.pan,r.age};}}
    for(std::size_t n=0;n<s.voices.size();++n){const auto& v=s.voices[n];out.voices[n]={v.port,v.slot,v.note,v.group,v.velocity,v.sample.bdOffset,v.position,v.step,v.cachedBend,int(v.envelope.phase),v.envelope.value,v.envelope.countdown,v.envelope.first,v.envelope.second,v.active};}
    if(s.pathLog)for(const auto& p:s.pathCounters)for(const auto& c:p){out.diagnostics.active_voice_frames+=c.activeVoiceFrames;out.diagnostics.signal_voice_frames+=c.signalVoiceFrames;out.diagnostics.requests+=c.requests;}
    return out;
}
